=== FILE: skid_buffer.v ===
`timescale 1ns/1ps
`default_nettype none

// skid_buffer: register slice for one valid/ready stream.
// Implements microarchitecture.md (two registers: output + skid).
// Every output is a flop or the inverse of one.
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // The output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // An upstream beat moves on this edge.
    wire s_fire = s_valid && s_ready;

    assign s_ready = !skid_valid;

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else if (m_free) begin
            if (skid_valid) begin
                m_valid    <= 1'b1;
                skid_valid <= 1'b0;
            end else begin
                m_valid    <= s_valid;
            end
        end else if (s_fire) begin
            skid_valid <= 1'b1;
        end
    end

    // Data registers: not reset; each loads only in its control's row.
    always @(posedge clk) begin
        if (m_free) begin
            if (skid_valid) begin
                m_data <= skid_data;
            end else begin
                m_data <= s_data;
            end
        end
        if (!m_free && s_fire) begin
            skid_data <= s_data;
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not proven here).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            // The skid register is only full while the output register is.
            assert(!skid_valid || m_valid);
            // Reset drops every held beat.
            if (!$past(rst_n)) begin
                assert(!m_valid);
                assert(!skid_valid);
            end
            // Hold: a stalled beat stays offered with the same data.
            if ($past(rst_n) && $past(m_valid) && !$past(m_ready)) begin
                assert(m_valid);
                assert(m_data == $past(m_data));
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
