`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
// Both lanes see the same handshakes; one queue model checks both.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg  [7:0] s_data;
    reg        m_ready;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready8), .s_data(s_data),
        .m_valid(m_valid8), .m_ready(m_ready), .m_data(m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready1), .s_data(s_data[0:0]),
        .m_valid(m_valid1), .m_ready(m_ready), .m_data(m_data1)
    );

    always #5 clk = ~clk;

    integer passed;
    integer failed;

    // Model: queue of up to two beats.
    integer    cnt;
    reg  [7:0] q0;
    reg  [7:0] q1;
    reg        model_ok;
    integer    in_count;
    integer    out_count;
    reg        hold_exp;
    reg  [7:0] hold_data;
    reg        hold_q;
    reg  [7:0] hold_d;
    reg        sfire;
    reg        mfire;

    // Glitch-check snapshots.
    reg        sr8_b, sr1_b, mv8_b, mv1_b, md1_b;
    reg  [7:0] md8_b;

    reg  [8*64-1:0] nonce;
    reg             verdict_done;

    integer    seed;
    integer    i;
    integer    phase;
    integer    base_in;
    integer    base_out;
    reg [31:0] rnd;
    reg  [7:0] k;
    reg        sv_r;
    reg        mr_r;

    task check(input cond, input [8*64-1:0] msg);
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("%0t: check failed: %0s", $time, msg);
            end
        end
    endtask

    task finish_run;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    task check_outputs;
        begin
            if (model_ok) begin
                check(s_ready8 === (cnt < 2), "s_ready8 matches model");
                check(s_ready1 === (cnt < 2), "s_ready1 matches model");
                check(m_valid8 === (cnt > 0), "m_valid8 matches model");
                check(m_valid1 === (cnt > 0), "m_valid1 matches model");
                if (cnt > 0) begin
                    check(m_data8 === q0, "m_data8 is the oldest beat");
                    check(m_data1[0] === q0[0], "m_data1 is the oldest beat");
                end
                if (hold_exp) begin
                    check(m_valid8 === 1'b1 && m_data8 === hold_data, "hold: stalled beat stays (W8)");
                    check(m_valid1 === 1'b1 && m_data1[0] === hold_data[0], "hold: stalled beat stays (W1)");
                end
            end
        end
    endtask

    // One clock cycle: drive at negedge, check, glitch-check, then the edge.
    task cycle(input rst_i, input sv_i, input [7:0] sd_i, input mr_i);
        begin
            @(negedge clk);
            rst_n   = rst_i;
            s_valid = sv_i;
            s_data  = sd_i;
            m_ready = mr_i;
            #1;
            check_outputs;
            if (model_ok) begin
                sr8_b = s_ready8; sr1_b = s_ready1;
                mv8_b = m_valid8; mv1_b = m_valid1;
                md8_b = m_data8;  md1_b = m_data1[0];
                s_valid = ~sv_i;
                m_ready = ~mr_i;
                s_data  = ~sd_i;
                #1;
                check(s_ready8 === sr8_b && s_ready1 === sr1_b, "s_ready steady within cycle");
                check(m_valid8 === mv8_b && m_valid1 === mv1_b, "m_valid steady within cycle");
                check(m_data8 === md8_b && m_data1[0] === md1_b, "m_data steady within cycle");
                s_valid = sv_i;
                m_ready = mr_i;
                s_data  = sd_i;
            end
            #1;
            sfire  = rst_i && sv_i && (cnt < 2);
            mfire  = rst_i && mr_i && (cnt > 0);
            hold_q = rst_i && (cnt > 0) && !mr_i;
            hold_d = q0;
            @(posedge clk);
            if (!rst_i) begin
                cnt      = 0;
                model_ok = 1'b1;
                hold_exp = 1'b0;
            end else if (model_ok) begin
                if (mfire) begin
                    q0        = q1;
                    cnt       = cnt - 1;
                    out_count = out_count + 1;
                end
                if (sfire) begin
                    if (cnt == 0) q0 = sd_i;
                    else          q1 = sd_i;
                    cnt      = cnt + 1;
                    in_count = in_count + 1;
                end
                hold_exp  = hold_q;
                hold_data = hold_d;
            end
        end
    endtask

    initial begin
        #2000000;
        failed = failed + 1;
        $error("timeout: testbench did not finish");
        finish_run;
    end

    initial begin
        clk          = 1'b0;
        rst_n        = 1'b0;
        s_valid      = 1'b0;
        s_data       = 8'h00;
        m_ready      = 1'b0;
        passed       = 0;
        failed       = 0;
        cnt          = 0;
        q0           = 8'h00;
        q1           = 8'h00;
        model_ok     = 1'b0;
        in_count     = 0;
        out_count    = 0;
        hold_exp     = 1'b0;
        hold_data    = 8'h00;
        verdict_done = 1'b0;
        seed         = 32'h5eed_1234;
        k            = 8'h40;

        // T1: reset values (inputs active during reset must not load).
        cycle(1'b0, 1'b1, 8'h11, 1'b1);
        cycle(1'b0, 1'b1, 8'h22, 1'b0);
        #1;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset: m_valid low");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset: s_ready high");

        // T2: one-cycle latency.
        cycle(1'b1, 1'b1, 8'hA5, 1'b1);
        #1;
        check(m_valid8 === 1'b1 && m_data8 === 8'hA5, "latency: beat offered after edge (W8)");
        check(m_valid1 === 1'b1 && m_data1 === 1'b1, "latency: beat offered after edge (W1)");
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "latency: slice drained");

        // T3: long stream at full throughput.
        base_in  = in_count;
        base_out = out_count;
        for (i = 0; i < 64; i = i + 1) begin
            cycle(1'b1, 1'b1, k, 1'b1);
            k = k + 8'd1;
            #1;
            check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "throughput: s_ready stays high");
            check(m_valid8 === 1'b1 && m_valid1 === 1'b1, "throughput: no bubble");
        end
        check(in_count - base_in == 64, "throughput: 64 beats accepted");
        check(out_count - base_out == 63, "throughput: 63 beats delivered");
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        check(out_count - base_out == 64, "throughput: all 64 delivered");
        check(m_valid8 === 1'b0, "throughput: drained");

        // T4: stall with one beat held, then with two.
        cycle(1'b1, 1'b1, 8'hC1, 1'b0);
        #1;
        check(m_valid8 === 1'b1 && m_data8 === 8'hC1, "stall: one beat held");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "stall: one held, s_ready high");
        cycle(1'b1, 1'b1, 8'hC2, 1'b0);
        #1;
        check(s_ready8 === 1'b0 && s_ready1 === 1'b0, "stall: two held, s_ready low");
        check(m_data8 === 8'hC1, "stall: oldest beat still offered");
        cycle(1'b1, 1'b1, 8'hC3, 1'b0);
        #1;
        check(s_ready8 === 1'b0 && m_data8 === 8'hC1, "stall: third beat refused");
        cycle(1'b1, 1'b1, 8'hC3, 1'b0);
        #1;
        check(s_ready8 === 1'b0 && m_data8 === 8'hC1, "stall: hold over long stall");

        // T5: ready rises after the stall.
        cycle(1'b1, 1'b1, 8'hC3, 1'b1);
        #1;
        check(m_valid8 === 1'b1 && m_data8 === 8'hC2, "release: skid beat to output");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "release: s_ready rises");
        cycle(1'b1, 1'b1, 8'hC3, 1'b1);
        #1;
        check(m_valid8 === 1'b1 && m_data8 === 8'hC3, "release: no bubble, C3 next");
        cycle(1'b1, 1'b1, 8'hC4, 1'b1);
        #1;
        check(m_valid8 === 1'b1 && m_data8 === 8'hC4, "release: C4 next");
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "release: drained");
        check(in_count == out_count, "release: every beat out once");

        // T6: random traffic against the model, in biased phases.
        for (phase = 0; phase < 4; phase = phase + 1) begin
            for (i = 0; i < 800; i = i + 1) begin
                rnd = $random(seed);
                case (phase)
                    0: begin sv_r = rnd[0] | rnd[3];  mr_r = rnd[1] & rnd[2]; end
                    1: begin sv_r = rnd[0] & rnd[3];  mr_r = rnd[1] | rnd[2]; end
                    2: begin sv_r = rnd[0];           mr_r = rnd[1];          end
                    default: begin sv_r = rnd[0] | rnd[3] | rnd[4]; mr_r = 1'b1; end
                endcase
                cycle(1'b1, sv_r, rnd[15:8], mr_r);
            end
        end
        // Drain.
        for (i = 0; i < 4; i = i + 1) begin
            cycle(1'b1, 1'b0, 8'h00, 1'b1);
        end
        #1;
        check(cnt == 0, "random: model drained");
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "random: DUT drained");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "random: s_ready high when empty");
        check(in_count == out_count, "random: every beat out exactly once");

        // T7: reset with beats held.
        cycle(1'b1, 1'b1, 8'hE1, 1'b0);
        cycle(1'b1, 1'b1, 8'hE2, 1'b0);
        #1;
        check(s_ready8 === 1'b0 && m_valid8 === 1'b1, "pre-reset: slice full");
        cycle(1'b0, 1'b1, 8'hE3, 1'b1);
        #1;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset with beats: m_valid low");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset with beats: s_ready high");
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        check(m_valid8 === 1'b0, "after reset: no stale beat");
        cycle(1'b1, 1'b1, 8'h5A, 1'b1);
        #1;
        check(m_valid8 === 1'b1 && m_data8 === 8'h5A, "after reset: new beat flows");
        cycle(1'b1, 1'b0, 8'h00, 1'b1);
        #1;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "after reset: drained");

        finish_run;
    end

endmodule

`default_nettype wire
=== END FILE ===
